#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const int M = 998244353;
int n;
bool ge(int i, int lo, int hi, int w){
    
    return lo<=hi && (w?hi-max(i,lo)+1>=(n-i+1)/2 + 1: min(i,hi)-lo+1>=i/2+1);
}
bool ok(int i, int u, int l, int d){
    int lo = l +1,hi = n-u+1+l,l2= lo+!d,h2 = hi-d;
    return (ge(i,lo,hi,0)&& !ge(i,l2,h2,0)) || (ge(i,lo,hi,1) && !ge(i,l2,h2,1));
}
void solve(){
    cin >> n;
    vector<vector<int>> g(n+1);
    for(int i=1;i<=n;i++){
        int a; cin >> a;
        g[a].push_back(i);
    }
    
    vector<int> dp(n+2,0);
    dp[0] =1;
    for(int u=1;u<n;u++){
        vector<int> nd(n+2,0);
        for(int l=0;l<u;l++){
            if(!dp[l])continue;
            for(int d=0;d<2;d++){
                bool f= true;
                for(int i:g[u]){
                    if(!ok(i,u,l,d)) {
                        f = false;
                        break;
                    }
                }
                if(f) nd[l+!d] = (nd[l+!d] + dp[l]) %M;
            }
        }
        dp = move(nd);
    }
    
    ll r =0;
    for(int l = 0;l<n;l++){
        if(!dp[l])continue;
        bool f = true;
        for(int i:g[n]){
            if(!ok(i,n,l,0)){
                f = false; break;
            }
        }
        if(f) r = (r+dp[l]) % M;
    }
    cout << r<< '\n';
}
int main() {
	// your code goes here
    ios::sync_with_stdio(0),cin.tie(0);
    int t;
    cin>> t;
    while(t--){
        solve();
    }
    return 0;
}
